ALTER TABLE users ADD COLUMN phone CHARACTER VARYING(50);
ALTER TABLE users ADD COLUMN username CHARACTER VARYING(100);

-- Note: password_hash and role fields may not be needed since we have password and user_type
-- Let's verify what the application actually uses

