-- === VERIFICATION QUERIES ===
-- Verify all fixes were applied

-- Check clients table
SELECT column_name, data_type, is_nullable 
FROM information_schema.columns 
WHERE table_name = 'clients' 
AND column_name = 'notes';

-- Check users table (show new fields)
SELECT column_name, data_type, is_nullable 
FROM information_schema.columns 
WHERE table_name = 'users' 
AND column_name IN ('first_name', 'last_name', 'phone', 'username');

-- Show all current columns in key tables
SELECT table_name, COUNT(*) as column_count
FROM information_schema.columns 
WHERE table_name IN ('tickets', 'clients', 'users', 'staff_profiles', 'contracts')
GROUP BY table_name
ORDER BY table_name;

-- Final verification of tickets table (our main concern)
SELECT column_name, data_type, character_maximum_length, is_nullable
FROM information_schema.columns 
WHERE table_name = 'tickets' 
AND column_name IN ('requested_by', 'requested_by_email', 'csr_sn', 'pi_number')
ORDER BY ordinal_position;